                 POST /GetFilteredLocations
                 {
                  "ProviderId": 2000069665,
                  "LocationIds": [
                    2005862796, 2005901195
                  ],
                  "StateIds": [
                    30, 32
                  ],
                  "IncludeClosedLocations": "false"
                 }

